<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids; use Illuminate\Database\Eloquent\Model;
class SalesOrder extends Model { use HasUuids; protected $fillable=['tenant_id','company_id','branch_id','currency_id','exchange_rate','base_total','customer_id','customer_contact_id','quotation_id','created_by','assigned_salesperson_id','number','state','order_date','requested_delivery_date','customer_reference','shipping_address','billing_address','shipping_method','delivery_instructions','payment_terms','internal_notes','reservation_status','fulfillment_status','payment_status','backorder_policy','hold_reason','confirmed_by','confirmed_at','subtotal','discount_total','tax_total','total']; protected function casts(): array { return ['exchange_rate'=>'decimal:12','base_total'=>'decimal:6','subtotal'=>'decimal:6','discount_total'=>'decimal:6','tax_total'=>'decimal:6','total'=>'decimal:6','order_date'=>'date','requested_delivery_date'=>'date','confirmed_at'=>'datetime']; } public function items(){return $this->hasMany(SalesOrderItem::class);} public function customer(){return $this->belongsTo(Customer::class);} public function customerContact(){return $this->belongsTo(CustomerContact::class);} public function quotation(){return $this->belongsTo(SalesQuotation::class);} public function approvals(){return $this->hasMany(SalesApproval::class);} public function reservations(){return $this->hasMany(StockReservation::class);} public function statusHistory(){return $this->hasMany(SalesOrderStatusHistory::class);} public function assignedSalesperson(){return $this->belongsTo(User::class,'assigned_salesperson_id');} }
